        <script>
            window.activeRequestId = null;
            function openRequestMenu(button, id) { window.activeRequestId = id; const menu = document.getElementById('request-menu'); const rect = button.getBoundingClientRect(); menu.style.left = Math.max(8, rect.right - 224) + 'px'; menu.style.top = (rect.bottom + 6) + 'px'; menu.classList.remove('hidden'); }
            function openPrPreview(id) { window.activeRequestId = id; document.getElementById('request-menu').classList.add('hidden'); document.getElementById('pr-frame').src = '{{ url('/procurement') }}/' + id + '/print'; document.getElementById('pr-preview').classList.remove('hidden'); }
            function closePrPreview() { document.getElementById('pr-preview').classList.add('hidden'); document.getElementById('pr-frame').src = ''; }
            function printPrPreview() { document.getElementById('pr-frame').contentWindow.print(); }
            function editRequest(id) { window.location.href = '{{ url('/procurement') }}/' + id + '/edit'; }
            function manageDocuments(id) { window.location.href = '{{ url('/procurement') }}/' + id + '/documents'; }
            function addMoreGoods(id) { window.location.href = '{{ url('/procurement') }}/' + id + '/edit#items'; }
            document.addEventListener('click', function(event) { if (!event.target.closest('#request-menu') && !event.target.closest('[title="More actions"]')) document.getElementById('request-menu').classList.add('hidden'); });
        </script>
